css:
/* Atelier Martha — global layer. Kyrix style: margin reset on headings and p,
   heading sizes as a clamp chain (min = next heading's max). */
@font-face{font-family:"Geist";font-style:normal;font-weight:100 900;font-display:swap;src:url(/wp-content/plugins/velox/assets/fonts/geist-latin-wght-normal.woff2) format("woff2-variations");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
@font-face{font-family:"Geist";font-style:normal;font-weight:100 900;font-display:swap;src:url(/wp-content/plugins/velox/assets/fonts/geist-latin-ext-wght-normal.woff2) format("woff2-variations");unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF}
:root{--am-ink:#17140f;--am-paper:#faf8f4;--am-sand:#f1ece3;--am-muted:#6b6358;--am-acc:#a5672b;--vxs-accent:#17140f;--vxs-ink:#17140f;--vxs-ink-2:#4f483f;--vxs-ink-3:#6b6358;--vxs-soft:#f1ece3;--vxs-line:rgba(23,20,15,.1);--vxs-sale:#a5672b;--vxs-r:18px}
html{scroll-behavior:smooth;scroll-padding-top:110px}
body{font-family:"Geist",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:var(--am-paper);color:var(--am-ink);-webkit-font-smoothing:antialiased;letter-spacing:-.01em}
body h1,body h2,body h3,body h4,body h5,body h6,body p{margin:0}
body h1,body h2,body h3,body h4,body h5,body h6{color:inherit;font-weight:600;letter-spacing:-.035em;line-height:1.08}
body h1{font-size:clamp(3rem,2rem + 3.6vw,4.75rem)}
body h2{font-size:clamp(2.25rem,1.6rem + 2.4vw,3rem)}
body h3{font-size:clamp(1.375rem,1.1rem + .9vw,2.25rem);line-height:1.2;letter-spacing:-.02em}
body h3:where(.am-step h3,.am-price h3){font-size:1.375rem}
body h4{font-size:clamp(1.125rem,1rem + .5vw,1.375rem)}
body h5{font-size:clamp(1rem,.95rem + .3vw,1.125rem)}
body h6{font-size:1rem}
.am-grad{background:linear-gradient(100deg,#a5672b 0%,#d9a35b 55%,#a5672b 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
.am-bg-dark .am-grad{background:linear-gradient(100deg,#d9a35b,#f1cf96 60%,#d9a35b)}
a{color:inherit}
::selection{background:#e9cfa6;color:#17140f}
/* buttons: the arrow turns on hover */
.am-btn:hover .am-btn-ic{transform:rotate(45deg)}
.am-btn:focus-visible,.am-cart:focus-visible,.am-side-ic:focus-visible{outline:3px solid rgba(165,103,43,.45);outline-offset:3px}
/* navbar: an underline that sweeps in from the left, and stays for the current page */
.am-nav a{position:relative;text-decoration:none;color:var(--am-ink);padding:6px 0}
.am-nav a::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;border-radius:2px;background:linear-gradient(90deg,#a5672b,#d9a35b);transform:scaleX(0);transform-origin:right;transition:transform .35s cubic-bezier(.6,0,.2,1)}
.am-nav a:hover::after,.am-nav a[aria-current="page"]::after,.am-nav a.active::after{transform:scaleX(1);transform-origin:left}
.am-nav a[aria-current="page"],.am-nav a.active{font-weight:600}
.am-cart .vxs-cartbtn{color:inherit}.am-cart .vxs-count{top:-4px;left:auto;right:-4px;background:#a5672b}
/* hero art */
.am-hero-art img{width:100%;height:100%;object-fit:cover}
.am-chip-t b{display:block;color:var(--am-ink);font-weight:600;font-size:14px}
.am-faq .vx-acc-item,.am-faq details{border-bottom:1px solid rgba(23,20,15,.1)}
/* footer */
.am-footer a{text-decoration:none;color:#b5ab9c;transition:color .2s}.am-footer a:hover{color:#f6f1e8}
.am-footer .am-withdraw:hover{border-color:#d9a35b;color:#fff}
/* shop pieces in the house style */
.vxs-btn{border-radius:999px;font-weight:600}
.vxs-card-media{border-radius:18px}
.vxs-cats a[aria-current=true]{background:#17140f;border-color:#17140f}
.vx-shop .vxs-grid{gap:44px 28px}
.am-content .vxs-checkout,.am-content .vxs-cartpage,.am-content .vxs-product{margin-top:0}
.am-content > .am-container > div > h2,.am-content h2{font-size:clamp(1.5rem,1.2rem + 1vw,2rem);margin:0 0 12px}
.am-content p{line-height:1.7}
@media (max-width:991px){.am-nav{display:none}}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}.am-btn,.am-nav a::after{transition:none}}
